body { margin: 0; font-family: Georgia, serif; color: #222; background: #faf8f4; }
.masthead { padding: 2rem 1.5rem 0; }
.divider { width: 100%; height: 12px; }
.content { max-width: 40rem; padding: 1rem 1.5rem 3rem; }
.feature { max-width: 100%; }
.button { display: inline-block; padding: 0.5rem 1rem; background: #2e5d3b; color: #fff; cursor: pointer; }
.button:hover { background: #234a2e; }
input[type="email"] { padding: 0.5rem; width: 16rem; }

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

const html = readFileSync('index.html', 'utf8');

function imgTag(src) {
  const tags = [...html.matchAll(/<img\b[^>]*>/gi)].map((m) => m[0]);
  const tag = tags.find((t) => t.includes(src));
  assert.ok(tag, `an img referencing ${src} still exists`);
  return tag;
}
function altOf(tag, src) {
  const alt = tag.match(/\balt\s*=\s*("([^"]*)"|'([^']*)')/i);
  assert.ok(alt, `image ${src} carries an alt attribute`);
  return alt[2] ?? alt[3] ?? '';
}

// 1) Meaningful images: specific, non-empty alt text.
for (const src of ['harvest-crew', 'seed-chart']) {
  const alt = altOf(imgTag(src), src).trim();
  assert.ok(alt.length >= 10, `alt for ${src} must be specific, got "${alt}"`);
  assert.ok(!/^(image|photo|picture|graphic|img)$/i.test(alt), `alt for ${src} must not be filler`);
  assert.ok(!/^(an? )?(image|photo|picture) of/i.test(alt), `alt for ${src} must not open with "image of"`);
}
console.log('A11YRETRO_ORACLE alts ok');

// 2) The decorative divider keeps an EMPTY alt - no sprayed description.
assert.equal(altOf(imgTag('divider'), 'divider').trim(), '', 'decorative divider keeps alt=""');
console.log('A11YRETRO_ORACLE decorative ok');

// 3) The email input is labeled by a real label whose for resolves to its id.
const labels = [...html.matchAll(/<label\b[^>]*\bfor\s*=\s*["']([^"']+)["'][^>]*>/gi)];
assert.ok(labels.length >= 1, 'a label element with a for attribute exists');
const paired = labels.filter((m) => new RegExp(`<input\\b[^>]*\\bid\\s*=\\s*["']${m[1]}["']`, 'i').test(html));
assert.ok(paired.length >= 1, "a label's for attribute resolves to a real input id");
console.log('A11YRETRO_ORACLE label ok');

// 4) The join control is a real button, or carries complete ARIA button semantics.
const join = html.match(/<([a-z0-9]+)\b([^>]*)>\s*Join the list/i);
assert.ok(join, 'the "Join the list" control still exists');
const [, joinTag, joinAttrs] = join;
if (joinTag.toLowerCase() !== 'button') {
  assert.ok(/\brole\s*=\s*["']button["']/i.test(joinAttrs), 'non-button control carries role="button"');
  assert.ok(/\btabindex\s*=\s*["']0["']/i.test(joinAttrs), 'non-button control is focusable via tabindex="0"');
  const keyWired = /\bonkey(?:down|up|press)\s*=/i.test(joinAttrs) || /addEventListener\s*\(\s*["']key(?:down|up|press)["']/i.test(html);
  assert.ok(keyWired, 'non-button control has keyboard activation wired');
}
console.log('A11YRETRO_ORACLE control ok');

// 5) Heading order is monotonic from a single h1.
const levels = [...html.matchAll(/<h([1-6])\b[^>]*>/gi)].map((m) => Number(m[1]));
assert.ok(levels.length >= 3, 'the page keeps its headings');
assert.equal(levels[0], 1, 'the page starts at h1');
for (let i = 1; i < levels.length; i++) {
  assert.ok(levels[i] <= levels[i - 1] + 1, `heading level jumps from h${levels[i - 1]} to h${levels[i]}`);
}
console.log('A11YRETRO_ORACLE headings ok');

// 6) The join behavior target survives the retrofit.
assert.ok(/joined-note/.test(html), 'the joined-note behavior target survives');
console.log('A11YRETRO_ORACLE done');
